          if (attack === "executable") entry = leaf(item.path, item[`${selected}_blob`], "100755");
          if (attack === "symlink") entry = leaf(item.path, item[`${selected}_blob`], "120000");
          if (attack === "submodule") entry = { path: item.path, mode: "160000", type: "commit", sha: originCommit };
          if (attack === "directory") entry = { path: item.path, mode: "040000", type: "tree", sha: empty };
          leaves.push(entry);
